'use strict';
const $=s=>document.querySelector(s),norm=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const MEDICATIONS=window.CHECKLISTS,GUIDES=window.GUIDES,DOCUMENT=window.DOCUMENT;
const FICHES=[...MEDICATIONS,...GUIDES];
const CONFIG={
 presentation:{title:'Présentation',hint:'Vérifier le produit et la présentation réellement disponibles. Mentions du livret.',action:'Présentation vérifiée'},
 indication:{title:'Indication',hint:'Cocher la ou les indications retenues dans la situation clinique. La confirmation appartient au prescripteur.',action:'Indication confirmée par l’utilisateur'},
 contra:{title:'Contre-indications',hint:'Chaque coche signifie « recherchée / vérifiée ». Elle ne signifie pas « absente » ni « autorisation d’administrer ». Conserver les distinctions absolues et relatives du livret.',action:'Contre-indication recherchée / vérifiée'},
 preparation:{title:'Préparation',hint:'Cocher les opérations effectuées pour la présentation et le schéma prescrits. Les conditions, diluants et concentrations restent associés au texte source.',action:'Préparation effectuée / contrôlée'},
 combined:{title:'Préparation et posologie associées',hint:'Le livret présente ces éléments ensemble. Ils restent regroupés pour conserver leurs conditions.',action:'Préparation / schéma contrôlé selon prescription'},
 dose:{title:'Posologie',hint:'Cocher uniquement le schéma applicable, relu et vérifié avec la prescription. Les alternatives ne sont pas des étapes à effectuer toutes ensemble. Une coche ne trace pas une administration.',action:'Schéma relu / choisi selon prescription'},
 surveillance:{title:'Installation et surveillance',hint:'Cocher les vérifications et mesures effectivement réalisées, selon les conditions de la fiche.',action:'Vérification / mesure effectuée'},
 effects:{title:'Effets indésirables',hint:'Cocher uniquement en cas d’apparition chez le patient. Une absence de coche signifie « non renseigné ». Ces observations sont séparées des étapes de préparation et de surveillance.',action:'Observé chez le patient'},
 notes:{title:'Précisions du livret',hint:'Mentions complémentaires conservées avec leur page source.',action:'Mention relue'}
};
const ORDER=['presentation','indication','contra','preparation','combined','dose','surveillance','effects','tables','notes'];
let population='tous',selected=MEDICATIONS[0],section='all',onlyFavorites=false,sourceOpen=false,favorites=[];
const checked=new Set();
try{const v=JSON.parse(localStorage.getItem('urgara-favorites')||'[]');if(Array.isArray(v))favorites=v}catch{}
function el(tag,cls,text){const node=document.createElement(tag);if(cls)node.className=cls;if(text!==undefined)node.textContent=text;return node}
function results(){return FICHES.filter(f=>(population==='tous'?f.category==='medicament':f.population===population)&&(!onlyFavorites||f.pages.some(p=>favorites.includes(p)))&&norm(f.text).includes(norm($('#search').value)))}
function pdfTarget(page){if(page>=21&&page<=64)return 'livret-adulte.pdf#page='+page;if(page>=65&&page<=104)return 'livret-pediatrique.pdf#page='+(page-44);return 'livret-source.pdf#page='+page}
function pdfLink(page,label,cls=''){const a=el('a',cls,label);a.href=pdfTarget(page);a.target='_blank';a.rel='noopener';return a}
function list(){const rows=results();$('#count').textContent=rows.length+' checklist'+(rows.length>1?'s':'')+' · '+({tous:'Tous les médicaments',adulte:'Adulte',pediatrie:'Pédiatrie',reperes:'Repères généraux'}[population]);$('#list').replaceChildren();for(const f of rows){const b=el('button','card'+(f.page===selected.page?' selected':''));b.setAttribute('aria-pressed',f.page===selected.page);b.append(el('strong','',f.title),el('span','',(population==='tous'?(f.population==='adulte'?'Adulte · ':'Pédiatrie · '):'')+(f.context?f.context+' · ':'')+'p. '+f.pages.join(', ')+(f.pages.some(p=>favorites.includes(p))?' ★':'')));b.onclick=()=>select(f);$('#list').append(b)}if(!rows.length)$('#list').append(el('p','muted','Aucune fiche. Essayez une autre recherche.'));updateNavigation()}
function updateNavigation(){const rows=results(),i=rows.findIndex(f=>f.page===selected.page);$('#prev').disabled=i<=0;$('#next').disabled=i<0||i>=rows.length-1}
function source(){const panel=$('#source-panel');panel.hidden=!sourceOpen;$('#source-toggle').setAttribute('aria-expanded',sourceOpen);$('#source-toggle').textContent=sourceOpen?'Masquer l’aperçu':'Aperçu des pages';$('#source-pages').replaceChildren();if(!sourceOpen)return;for(const p of selected.pages){const wrap=el('div','source-page'),line=el('p');line.append(pdfLink(p,'Ouvrir la page '+p+' du PDF ↗'));const img=el('img');img.src='assets/page-'+p+'.jpg';img.alt='Page originale '+p+' — '+selected.title;img.loading='lazy';wrap.append(line,img);$('#source-pages').append(wrap)}}
function select(f,updateHash=true){selected=f;if(!(population==='tous'&&f.category==='medicament'))population=f.population;showView(f.category==='guide'?'reperes':'medicaments');$('#detail').classList.toggle('reference-guide',f.category==='guide');section='all';sourceOpen=false;$('#title').textContent=f.title;$('#context').textContent=f.context;$('#population').textContent=f.category==='guide'?'REPÈRE GÉNÉRAL · LIVRET MCS':f.population==='adulte'?'ADULTE · CHECKLIST DU MÉDICAMENT':'PÉDIATRIE · VÉRIFIER POIDS, ÂGE ET LIMITES';$('#page').textContent='Source : livret MCS · page'+(f.pages.length>1?'s ':' ')+f.pages.join(', ');const isFavorite=f.pages.some(p=>favorites.includes(p));$('#star').textContent=isFavorite?'★':'☆';$('#star').setAttribute('aria-pressed',isFavorite);$('#star').setAttribute('aria-label',isFavorite?'Retirer des favoris':'Ajouter aux favoris');document.querySelectorAll('[data-pop]').forEach(b=>{b.classList.toggle('active',b.dataset.pop===population);b.setAttribute('aria-pressed',b.dataset.pop===population)});$('#warnings').replaceChildren(...f.warnings.map(w=>el('p','warning',w)));$('#source-open').href=pdfTarget(f.page);$('#source-open').textContent=f.category==='guide'?'Ouvrir le PDF source ↗':f.population==='adulte'?'Ouvrir le PDF adulte ↗':'Ouvrir le PDF pédiatrique ↗';source();list();render();if(updateHash&&location.hash!=='#fiche-'+f.page)history.replaceState(null,'','#fiche-'+f.page)}
function isInfo(key,item){return item.info||key==='notes'||(key==='effects'&&selected.page!==18&&/^(Sans objet|Aucun|Néant|Non renseign)/i.test(item.text))}
function updateSummary(){const all=Object.entries(selected.sections).flatMap(([key,items])=>items.map(item=>({key,item})));const n=all.filter(x=>x.key!=='effects'&&!isInfo(x.key,x.item)&&checked.has(x.item.id)).length+[...checked].filter(id=>id.startsWith(selected.page+'-table-')).length;const effects=all.filter(x=>x.key==='effects'&&!isInfo(x.key,x.item)&&checked.has(x.item.id));$('#progress').textContent=n+' élément'+(n>1?'s':'')+' coché'+(n>1?'s':'')+' · confirmation manuelle';$('#effect-count').textContent=effects.length?effects.length+' effet'+(effects.length>1?'s':'')+' signalé'+(effects.length>1?'s':''):'Effets indésirables : non renseignés';$('#effect-count').classList.toggle('observed',effects.length>0);$('#effect-count').hidden=!selected.sections.effects.length;if(selected.page===18)$('#effect-count').textContent=effects.length?effects.length+' signal / alarme observé(e)':'Signaux et alarmes : non renseignés';const indications=selected.sections.indication.filter(it=>checked.has(it.id));$('#confirmation').hidden=selected.category==='guide'&&!selected.sections.indication.length;$('#confirmation').textContent=indications.length?'Indication'+(indications.length>1?'s':'')+' confirmée'+(indications.length>1?'s':'')+' par vous : '+indications.map(it=>it.text).join(' · '):'Indication : aucune confirmation manuelle pour cette checklist.';}
function checkRow(key,item){const label=el('label','check-row'+(key==='effects'?' effect':'')+(checked.has(item.id)?' checked':'')),input=el('input');input.type='checkbox';input.checked=checked.has(item.id);input.dataset.item=item.id;const body=el('span','content');body.append(el('span','action-label',(selected.sectionConfig?.[key]?.action||CONFIG[key].action)),document.createTextNode(item.text));label.append(input);if(item.image){const img=el('img','pictogram'+(selected.page===15?' legend':''));img.src=item.image;img.alt='Pictogramme / étiquette originale : '+item.text;img.loading='lazy';label.append(img)}label.append(body,pdfLink(item.page,'p. '+item.page,'source-mini'));input.onchange=()=>{if(input.checked&&item.group){for(const other of Object.values(selected.sections).flat()){if(other.id!==item.id&&other.group===item.group){checked.delete(other.id);const peer=document.querySelector('[data-item="'+other.id+'"]');if(peer){peer.checked=false;peer.parentElement.classList.remove('checked')}}}}if(input.checked&&key==='dose'&&item.text.startsWith('RYTHME')){for(const other of selected.sections.dose){if(other.id!==item.id&&other.text.startsWith('RYTHME')){checked.delete(other.id);const peer=document.querySelector('[data-item="'+other.id+'"]');if(peer){peer.checked=false;peer.parentElement.classList.remove('checked')}}}}if(input.checked)checked.add(item.id);else checked.delete(item.id);label.classList.toggle('checked',input.checked);updateSummary()};return label}
function rubric(key){const cfg={...CONFIG[key],...selected.sectionConfig?.[key]},wrap=el('section','rubric');wrap.dataset.rubric=key;const head=el('div','rubric-heading');head.append(el('h3','',cfg.title),pdfLink(selected.page,'PDF source ↗'));wrap.append(head,el('p','rubric-hint',cfg.hint));const items=selected.sections[key];if(!items.length){const message=key==='effects'?'Aucun effet indésirable renseigné dans cette rubrique du livret. Cela ne signifie pas qu’il n’existe aucun risque.':key==='preparation'&&selected.sections.combined.length?'La préparation est décrite dans « Préparation et posologie associées ».':key==='dose'&&selected.sections.combined.length?'La posologie est décrite dans « Préparation et posologie associées ».':'Aucun élément séparé dans cette rubrique. Consulter les rubriques associées et le PDF source.';wrap.append(el('p','empty-section',message))}
let previousGroup='';for(const item of items.filter(it=>!isInfo(key,it))){if(item.groupLabel&&item.groupLabel!==previousGroup){wrap.append(el('p','group-label',item.groupLabel));previousGroup=item.groupLabel}wrap.append(checkRow(key,item))}const infos=items.filter(it=>isInfo(key,it));if(infos.length){const d=el('details','source-note'),s=el('summary','',key==='effects'?'Mention du livret':'Mentions et schémas du livret');d.append(s);if(key==='effects'||selected.category==='guide')d.open=true;for(const it of infos){const p=el('p','',it.text+' ');p.append(pdfLink(it.page,'(p. '+it.page+')'));d.append(p)}wrap.append(d)}return wrap}
function normalizeTable(t){let rows=t.rows.map(r=>[...r]),prefix=[];while(rows.length>1&&rows[0].filter(Boolean).length===1){prefix.push(rows.shift().filter(Boolean)[0])}if(rows.length>1&&/poids|âge|age/i.test(rows[0][0])&&rows[0].slice(1).every(c=>/^[<≥≤>]?\s*\d/.test(c))&&rows.every(r=>r.length===rows[0].length)){rows=rows[0].map((_,i)=>rows.map(r=>r[i]));}return{rows,prefix}}
function tablesRubric(){const wrap=el('section','rubric');wrap.dataset.rubric='tables';const head=el('div','rubric-heading');head.append(el('h3','','Tableaux de doses et de débits'),pdfLink(selected.page,'PDF source ↗'));wrap.append(head,el('p','rubric-hint','Lire les conditions, les en-têtes et les unités avant de cocher une ligne vérifiée. Aucun calcul ni choix automatique. Les préparations et limites des autres rubriques restent applicables.'));if(!selected.tables.length)wrap.append(el('p','empty-section','Pas de tableau distinct extrait pour cette fiche.'));for(const t of selected.tables){const{rows,prefix}=normalizeTable(t),caption=el('p','table-caption',(t.caption?t.caption+' · ':'')+'Tableau source p. '+t.page+' ');caption.append(pdfLink(t.page,'Comparer au PDF ↗'));wrap.append(caption);if(t.annotations?.length){const note=el('div','table-context');note.append(el('strong','','Mentions associées du PDF :'));for(const line of t.annotations)note.append(el('p','',line));wrap.append(note)}if(prefix.length){const context=el('div','table-context');for(const text of prefix)context.append(el('p','',text));wrap.append(context)}const scroll=el('div','table-wrap'),table=el('table','dose-table');const cap=el('caption','',t.caption||'Tableau du livret — page '+t.page);table.append(cap);rows.forEach((row,i)=>{const tr=el('tr'),hasData=/^(?:[<≥≤>]?\s*\d|P\s*[≥<>≤])/i.test(row[0])&&row.length>1;const control=el('td');if(hasData){const label=el('label'),input=el('input');input.type='checkbox';const id=t.id+'-row-'+i;input.checked=checked.has(id);input.setAttribute('aria-label','Ligne vérifiée : '+row.map((c,j)=>(rows[0][j]||'colonne '+(j+1))+': '+c).join(' ; '));input.onchange=()=>{input.checked?checked.add(id):checked.delete(id);tr.classList.toggle('checked',input.checked);updateSummary()};tr.classList.toggle('checked',input.checked);label.append(input,el('span','','Ligne vérifiée'));control.append(label)}else control.textContent='—';tr.append(control);for(const value of row)tr.append(el('td','',value));table.append(tr)});scroll.append(table);wrap.append(scroll)}return wrap}
function render(){document.querySelectorAll('[data-section]').forEach(b=>{b.classList.toggle('active',b.dataset.section===section);b.setAttribute('aria-pressed',b.dataset.section===section);const k=b.dataset.section;if(k!=='all'&&k!=='tables'){b.textContent=selected.sectionConfig?.[k]?.title||CONFIG[k]?.title||b.textContent}b.disabled=selected.category==='guide'&&k!=='all'&&(k==='tables'?!selected.tables.length:!(selected.sections[k]?.length||(k==='preparation'||k==='dose')&&selected.sections.combined.length))});$('#sections').replaceChildren();for(const key of (selected.sectionOrder||ORDER)){const show=section==='all'||section===key||(section==='preparation'&&(key==='presentation'||key==='combined'))||((section==='dose'||section==='tables')&&['presentation','preparation','combined','dose','tables'].includes(key));if(!show)continue;if(selected.category==='guide'&&key!=='tables'&&!selected.sections[key].length)continue;if(section==='all'&&key==='notes'&&!selected.sections.notes.length)continue;if(section==='all'&&key==='combined'&&!selected.sections.combined.length)continue;if(section==='all'&&key==='tables'&&!selected.tables.length)continue;$('#sections').append(key==='tables'?tablesRubric():rubric(key))}updateSummary()}
$('#search').oninput=list;document.querySelectorAll('[data-pop]').forEach(b=>b.onclick=()=>{population=b.dataset.pop;document.querySelectorAll('[data-pop]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});const first=results()[0];if(first)select(first);else list()});document.querySelectorAll('[data-section]').forEach(b=>b.onclick=()=>{section=b.dataset.section;render()});$('#favorites').onclick=()=>{onlyFavorites=!onlyFavorites;$('#favorites').classList.toggle('active',onlyFavorites);$('#favorites').setAttribute('aria-pressed',onlyFavorites);list()};$('#star').onclick=()=>{if(selected.pages.some(p=>favorites.includes(p)))favorites=favorites.filter(p=>!selected.pages.includes(p));else favorites.push(selected.page);try{localStorage.setItem('urgara-favorites',JSON.stringify(favorites))}catch{}const yes=selected.pages.some(p=>favorites.includes(p));$('#star').textContent=yes?'★':'☆';$('#star').setAttribute('aria-pressed',yes);$('#star').setAttribute('aria-label',yes?'Retirer des favoris':'Ajouter aux favoris');list()};$('#source-toggle').onclick=()=>{sourceOpen=!sourceOpen;source()};$('#reset').onclick=()=>{for(const k of [...checked])if(k.startsWith(selected.page+'-'))checked.delete(k);render()};for(const[id,delta]of [['prev',-1],['next',1]])$('#'+id).onclick=()=>{const rows=results(),i=rows.findIndex(f=>f.page===selected.page);if(i>=0&&i+delta>=0&&i+delta<rows.length)select(rows[i+delta])};function fromHash(){const page=Number(location.hash.replace('#fiche-',''));return FICHES.find(f=>f.pages.includes(page))}window.addEventListener('hashchange',()=>{const f=fromHash();if(f)select(f,false)});initLibrary();select(fromHash()||selected);
